#!/usr/bin/env node
// Vendor the built @ichava/react-icon-browser library into resources/vendor/react-icon-browser.
//
//   node .dev/tools/sync-react-icon-browser.mjs [path/to/react-icon-browser]
//
// The browser UI is react-icon-browser's, consumed as a built library. This package does not
// install it from git: the repository is private, so every CI run and every host rebuilding the
// assets would need a GitHub token, and an npm git dependency installs `src/` without the
// `dist/lib` build anyway. Instead the built output is vendored here, with a manifest naming the
// exact commit it was built from and a hash of every file, so a hand edit or a partial copy fails
// `resources/js/core/vendoredLibrary.test.ts`.
//
// Run `npm run build:lib` in the react-icon-browser checkout first (this script refuses a
// checkout whose dist/lib is missing or older than its HEAD commit), then run this, then
// `npm install` and `npm run build:prod` here.
//
// Not copied: index.js.map. Its sourcesContent is the readable library source, Untitled UI PRO
// included, and nothing at runtime reads it.

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..', '..');
const source = resolve(process.argv[2] ?? join(root, '..', 'react-icon-browser'));
const lib = join(source, 'dist', 'lib');
const target = join(root, 'resources', 'vendor', 'react-icon-browser');

const fail = (msg) => {
  console.error(`sync-react-icon-browser: ${msg}`);
  process.exit(1);
};

if (!existsSync(join(source, 'package.json'))) fail(`no package.json in ${source}`);
const pkg = JSON.parse(readFileSync(join(source, 'package.json'), 'utf8'));
if (pkg.name !== '@ichava/react-icon-browser') fail(`${source} is ${pkg.name}, not @ichava/react-icon-browser`);
if (!existsSync(join(lib, 'index.js'))) fail(`no ${relative(root, lib)}/index.js; run \`npm run build:lib\` there first`);

const git = (...args) => execFileSync('git', ['-C', source, '-c', 'core.fsmonitor=false', ...args], { encoding: 'utf8' }).trim();
const commit = git('rev-parse', 'HEAD');
const dirty = git('status', '--porcelain', '--untracked-files=no', '--', 'src', 'package.json', 'vite.lib.config.ts');
if (dirty) fail(`${source} has uncommitted changes under src/ or the build config; vendor a commit, not a working tree`);
const committedAt = Number(git('log', '-1', '--format=%ct')) * 1000;
if (statSync(join(lib, 'index.js')).mtimeMs < committedAt) fail('dist/lib is older than HEAD; rebuild it with `npm run build:lib`');

rmSync(target, { recursive: true, force: true });
mkdirSync(target, { recursive: true });
cpSync(lib, target, { recursive: true, filter: (src) => !src.endsWith('.map') });
cpSync(join(source, 'LICENSE'), join(target, 'LICENSE'));
// The map is not shipped, so drop the comment pointing at it (bundlers warn on a missing map).
const entry = join(target, 'index.js');
writeFileSync(entry, readFileSync(entry, 'utf8').replace(/\n\/\/# sourceMappingURL=index\.js\.map\s*$/, '\n'));

// A package.json of its own, so `npm install` links it as `@ichava/react-icon-browser` and the
// adapter imports it by name. The peers stay peers (this package provides them); the kernel is a
// dependency because the declarations import its types (the JS has it bundled).
writeFileSync(
  join(target, 'package.json'),
  JSON.stringify(
    {
      name: pkg.name,
      version: pkg.version,
      private: true,
      license: pkg.license,
      type: 'module',
      description: 'Vendored build of @ichava/react-icon-browser. Generated by .dev/tools/sync-react-icon-browser.mjs; do not edit.',
      types: './types/index.d.ts',
      exports: {
        '.': { types: './types/index.d.ts', import: './index.js' },
        './styles.css': './styles.css',
        './package.json': './package.json',
      },
      sideEffects: ['./styles.css'],
      dependencies: { '@ichava/js-ui-kernel': pkg.dependencies['@ichava/js-ui-kernel'] },
      peerDependencies: pkg.peerDependencies,
    },
    null,
    2,
  ) + '\n',
);

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((d) => (d.isDirectory() ? walk(join(dir, d.name)) : [join(dir, d.name)]));

const files = Object.fromEntries(
  walk(target)
    .map((f) => relative(target, f).split(sep).join('/'))
    .filter((f) => f !== 'VENDORED.json')
    .sort()
    .map((f) => [f, createHash('sha256').update(readFileSync(join(target, f))).digest('hex')]),
);

writeFileSync(
  join(target, 'VENDORED.json'),
  JSON.stringify(
    {
      package: pkg.name,
      version: pkg.version,
      repository: 'https://github.com/ichava/react-icon-browser',
      commit,
      builtWith: 'npm run build:lib',
      files,
    },
    null,
    2,
  ) + '\n',
);

console.log(`sync-react-icon-browser: ${pkg.name}@${pkg.version} (${commit.slice(0, 7)}), ${Object.keys(files).length} files -> ${relative(root, target)}`);
